namespace qqworld_collector\module\cloud_storage; use qqworld_collector\module\cloudStorage2; class bohe extends cloudStorage2 { var $apiUrl; var $namingMode; var $uploadPath; public function init() { $this->apiUrl = $this->options->cloud_storage_bohe_api_url; $this->token = $this->options->cloud_storage_bohe_token; $this->namingMode = $this->options->cloud_storage_bohe_naming_mode; $this->uploadPath = $this->options->cloud_storage_bohe_upload_path; $this->silent_scanning = $this->options->cloud_storage_bohe_silent_scanning; $this->delete_attachment_after_synced = $this->options->cloud_storage_joinmode_enabled ? 0 : $this->options->cloud_storage_bohe_delete_attachment_after_synced; } public function upload($destination_path, $source_path) { if (!file_exists($source_path) || !filesize($source_path)) return false; if (function_exists('curl_file_create')) { $file = curl_file_create($source_path); } else { $file = '@' . realpath($source_path); } $post_data = [ 'uploadedFile' => new \CURLFile($source_path), 'api_token' => $this->token, 'upload_format'=> 'file', 'mode' => $this->namingMode, 'watermark' => 0 ]; if ($this->uploadPath) $post_data['uploadPath'] = $this->uploadPath; $ch = curl_init(); curl_setopt($ch, CURLOPT_URL, $this->apiUrl); curl_setopt($ch, CURLOPT_POST, 1); curl_setopt($ch, CURLOPT_SAFE_UPLOAD, true); curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1); curl_setopt($ch, CURLOPT_POSTFIELDS, $post_data); $result = curl_exec($ch); curl_close($ch); $result = json_decode($result, true); if ($result['statusCode'] == 200) { do_action( 'qqworld-collector-log', $this->log_id, 'bohe success:', print_r($result, true) ); $url = $result['url']; if (preg_match('/^http/i', $url)) return $url; else do_action( 'qqworld-collector-log', $this->log_id, 'bohe failed: ', print_r($result, true) ); } else { do_action( 'qqworld-collector-log', $this->log_id, 'bohe failed: ', print_r($result, true) ); } return false; } public function add_could_storage_form($guid) { $this->accessed = $t